import{_ as e,o as a,c as n,a4 as o}from"./chunks/framework.BLTfkDdN.js";const m=JSON.parse('{"title":"Apex Systems Engineering","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"book/index.md","repoSourcePath":"book/index.md"}'),r={name:"index.md"};function s(i,t,l,d,c,g){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="apex-systems-engineering" tabindex="-1">Apex Systems Engineering <a class="header-anchor" href="#apex-systems-engineering" aria-label="Permalink to &quot;Apex Systems Engineering&quot;">​</a></h1><p>This companion textbook is written for anyone with general programming experience and foundational math and physics literacy who wants to master processor architecture, circuit-board physics, motor control, and legged robotics from first principles.</p><div class="book-hero-banner"><div class="book-hero-stat"><span class="stat-num">8</span><span class="stat-label">Chronological Parts</span></div><div class="book-hero-stat"><span class="stat-num">34</span><span class="stat-label">Cohesive Chapters</span></div><div class="book-hero-stat"><span class="stat-num">186</span><span class="stat-label">Verified Steps and Labs</span></div><div class="book-hero-stat"><span class="stat-num">100%</span><span class="stat-label">Live-Synced Code</span></div></div><h2 id="preface" tabindex="-1">Preface <a class="header-anchor" href="#preface" aria-label="Permalink to &quot;Preface&quot;">​</a></h2><p><strong>Apex</strong> unifies digital logic, printed-circuit electromagnetics, compiler construction, power electronics, and dynamic control around a single cohesive machine: an indoor-safe (about 2.5 kg, under 22 V) autonomous quadruped built without throwaway prototypes. Across eight chronological parts, we design a custom 32-bit processor implementing the open-standard <strong>Reduced Instruction Set Computer, Fifth Generation</strong> (RISC-V) architecture and deploy it onto a reprogrammable logic chip (<strong>Field-Programmable Gate Array</strong>, or FPGA). We then route a 6-layer controlled-impedance circuit board, write a C compiler and a deterministic task scheduler (<strong>Real-Time Operating System</strong>, or RTOS), build 20 kHz brushless motor drives and solid-state battery protection, and close whole-body locomotion and stereo navigation loops.</p><p>Every chapter develops one primary engineering discipline—combining plain-language intuition, interactive schematics, concrete numbers, concise math, verified source code in <code>systems/</code>, and closing hardware bench labs—growing section by section as each implementation step lands.</p><h2 id="start-reading" tabindex="-1">Start Reading <a class="header-anchor" href="#start-reading" aria-label="Permalink to &quot;Start Reading&quot;">​</a></h2><p>The prologue establishes the locked electrical, mechanical, and communication contracts shared across all six subsystems, and Chapter 1 begins Part I by constructing the software golden reference processor. Every chapter pairs words, visuals, concrete numbers, concise math, and live-synced code excerpts designed to be read sequentially:</p><ul><li><strong><a href="/apex/vision">Prologue — System Architecture and Contracts</a></strong> — How the six physical subsystems bolt directly into the final quadruped without circuit-board redesigns or throwaway bench builds.</li><li><strong><a href="/apex/brain/01_isa_and_binary_arithmetic">Chapter 1 — Instruction Set Architecture</a></strong> — Software golden reference modeling, fixed-width modular binary arithmetic and two&#39;s complement, 32-bit instruction encoding, memory-mapped device registers, and fault or interrupt redirects (<strong>traps</strong>).</li></ul><h2 id="complete-syllabus" tabindex="-1">Complete Syllabus <a class="header-anchor" href="#complete-syllabus" aria-label="Permalink to &quot;Complete Syllabus&quot;">​</a></h2><p>The thirty-four chapters below follow the exact dependency order of <code>roadmap.yaml</code>, progressing from digital logic gates and board physics through actuators, power electronics, single-leg dynamics, quadruped walking, and stereo vision. Each part builds one major engineering layer and links directly to its subsystem reference contract.</p><h3 id="part-i-digital-logic-and-processor-architecture" tabindex="-1">Part I — Digital Logic and Processor Architecture <a class="header-anchor" href="#part-i-digital-logic-and-processor-architecture" aria-label="Permalink to &quot;Part I — Digital Logic and Processor Architecture&quot;">​</a></h3><p>Part I constructs the custom 32-bit <code>brain</code> processor from fixed-width binary arithmetic up to a 5-stage pipelined hardware design accelerated by a custom two-lane 16-bit <strong>Multiply-Accumulate</strong> (<code>mac</code>) instruction. Every combinational circuit, register file, arithmetic unit, and trap path is verified instruction-for-instruction against a software reference model and timing-closed on reprogrammable FPGA fabric (<a href="https://github.com/Ethanex8/apex/blob/main/systems/brain/README.md" target="_blank" rel="noreferrer"><code>brain</code> Reference</a>).</p><table tabindex="0"><thead><tr><th style="text-align:center;">Ch.</th><th style="text-align:left;">Title and Scope</th><th style="text-align:left;">Steps</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td style="text-align:left;"><strong><a href="/apex/brain/01_isa_and_binary_arithmetic">Instruction Set Architecture</a></strong><br>Golden reference modeling, modular binary arithmetic and two&#39;s complement, 32-bit instruction encoding, memory-mapped device registers, and hardware traps.</td><td style="text-align:left;"><code>brain-01</code></td><td style="text-align:center;"><span class="book-status-live">Published</span></td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td style="text-align:left;"><strong>Combinational and Sequential Logic</strong><br>Carry-chain adders, single-cycle barrel shifters, signed and unsigned comparators, clocked flip-flops, timing windows, 32×32 register files, and sign extension.</td><td style="text-align:left;"><code>brain-02</code> to <code>brain-03</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td style="text-align:left;"><strong>Clock Domains and Serial Framing</strong><br>Flip-flop metastability, two-stage synchronizers, 16×-oversampled serial framing with byte queues, and logic-analyzer hardware capture.</td><td style="text-align:left;"><code>brain-04</code> to <code>brain-05</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td style="text-align:left;"><strong>Single-Cycle Processor Design</strong><br>Control-table decoding, conditional branches, little-endian byte and halfword alignment, on-chip static memory, and 10k-instruction lockstep verification.</td><td style="text-align:left;"><code>brain-06</code> to <code>brain-08</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>5</strong></td><td style="text-align:left;"><strong>Multi-Cycle Arithmetic and Traps</strong><br>Valid/ready handshakes, shift-add multiply and restoring divide, two-lane 16-bit <code>mac</code> dot-product hardware, control registers, and 64-bit cycle timers.</td><td style="text-align:left;"><code>brain-09</code> to <code>brain-11</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>6</strong></td><td style="text-align:left;"><strong>Pipelined Processor Design</strong><br>Five-stage throughput versus latency, data-hazard forwarding networks, load-use stalls, precise trap flushes, 100k-instruction stress testing, and 50 MHz timing closure.</td><td style="text-align:left;"><code>brain-12</code> to <code>brain-16</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr></tbody></table><h3 id="part-ii-circuit-board-physics-and-memory-interconnects" tabindex="-1">Part II — Circuit-Board Physics and Memory Interconnects <a class="header-anchor" href="#part-ii-circuit-board-physics-and-memory-interconnects" aria-label="Permalink to &quot;Part II — Circuit-Board Physics and Memory Interconnects&quot;">​</a></h3><p>Part II moves off the bare processor core onto the central 6-layer Spine circuit board connecting the processor, battery, and leg buses, modeling copper traces as electromagnetic waveguides and designing clean switching power rails. We then build the on-chip memory crossbar, external flash and dynamic <strong>Random-Access Memory</strong> (RAM) controllers, and real-time sensor and motor-bus peripherals (<a href="https://github.com/Ethanex8/apex/blob/main/systems/brain/README.md" target="_blank" rel="noreferrer"><code>brain</code> Reference</a>).</p><table tabindex="0"><thead><tr><th style="text-align:center;">Ch.</th><th style="text-align:left;">Title and Scope</th><th style="text-align:left;">Steps</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>7</strong></td><td style="text-align:left;"><strong>Power Delivery and Transmission Lines</strong><br>Synchronous step-down switching physics, USB-C power negotiation, copper traces as waveguides, impedance reflections, and multi-stage ceramic capacitor networks.</td><td style="text-align:left;"><code>brain-17</code> to <code>brain-18</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>8</strong></td><td style="text-align:left;"><strong>Six-Layer Circuit Board Design</strong><br>Unbroken ground return planes, four-wire voltage sensing, series damping, 120 Ω differential bus termination, test coupons, length matching, and layout verification.</td><td style="text-align:left;"><code>brain-19</code> to <code>brain-23</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>9</strong></td><td style="text-align:left;"><strong>Memory Bus and External Controllers</strong><br>Address-decoded bus crossbars, 4-wire persistent flash direct-execution engines, and dynamic RAM capacitor refresh, row/column timing, and burst scheduling.</td><td style="text-align:left;"><code>brain-24</code> to <code>brain-26</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>10</strong></td><td style="text-align:left;"><strong>System-on-Chip Peripherals and Clocking</strong><br>Motion-sensor serial bursts, sub-microsecond camera shutter latching, differential motor-bus framing and checksums, phase-shifted clock capture, and dock boot.</td><td style="text-align:left;"><code>brain-27</code> to <code>brain-29</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr></tbody></table><h3 id="part-iii-compilers-and-real-time-operating-systems" tabindex="-1">Part III — Compilers and Real-Time Operating Systems <a class="header-anchor" href="#part-iii-compilers-and-real-time-operating-systems" aria-label="Permalink to &quot;Part III — Compilers and Real-Time Operating Systems&quot;">​</a></h3><p>Part III builds the complete software toolchain and operating kernel that run natively on our custom processor without external black-box libraries. We implement a two-pass assembler, linker, optimizing C subset compiler (SysC), preemptive real-time kernel, and custom-board hardware validation suite (<a href="https://github.com/Ethanex8/apex/blob/main/systems/brain/README.md" target="_blank" rel="noreferrer"><code>brain</code> Reference</a>).</p><table tabindex="0"><thead><tr><th style="text-align:center;">Ch.</th><th style="text-align:left;">Title and Scope</th><th style="text-align:left;">Steps</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>11</strong></td><td style="text-align:left;"><strong>Assembly and C Front-End Parsing</strong><br>Two-pass label resolution, upper/lower address relocations, Flash-to-RAM linker maps, lexical scanning, recursive-descent parsing, pointer typing, and intermediate lowering.</td><td style="text-align:left;"><code>brain-30</code> to <code>brain-32</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>12</strong></td><td style="text-align:left;"><strong>Compiler Optimization and Code Generation</strong><br>Fixed-point optimization with hardware-register ordering barriers, backward liveness, linear-scan register allocation, stack frames, <code>mac</code> emission, and equivalence checks.</td><td style="text-align:left;"><code>brain-33</code> to <code>brain-35</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>13</strong></td><td style="text-align:left;"><strong>Preemptive Real-Time Kernel</strong><br>Bare-metal startup, Flash-to-RAM bootloading, 31-register trap-scratchpad (<code>mscratch</code>) context switching, priority-inheritance locks, and single-producer ring buffers.</td><td style="text-align:left;"><code>brain-36</code> to <code>brain-37</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>14</strong></td><td style="text-align:left;"><strong>Fixed-Point Control and Bring-Up</strong><br>Scaled-integer attitude filtering, 1 kHz feedback jitter histograms, interactive <code>ash</code> serial shell, sub-millisecond 16-bit neural inference, trace-reflection sweeps, and board graduation.</td><td style="text-align:left;"><code>brain-38</code> to <code>brain-42</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr></tbody></table><h3 id="part-iv-brushless-motors-and-power-inverters" tabindex="-1">Part IV — Brushless Motors and Power Inverters <a class="header-anchor" href="#part-iv-brushless-motors-and-power-inverters" aria-label="Permalink to &quot;Part IV — Brushless Motors and Power Inverters&quot;">​</a></h3><p>Part IV develops the <code>drive</code> force-controlled joint actuator, deriving permanent-magnet brushless motor physics and rotating-frame current control from electromagnetic first principles. We design a 4-layer three-phase power inverter, write 20 kHz bare-metal motor firmware, and machine an 8:1 low-backlash planetary gearbox (<a href="https://github.com/Ethanex8/apex/blob/main/systems/drive/README.md" target="_blank" rel="noreferrer"><code>drive</code> Reference</a>).</p><table tabindex="0"><thead><tr><th style="text-align:center;">Ch.</th><th style="text-align:left;">Title and Scope</th><th style="text-align:left;">Steps</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>15</strong></td><td style="text-align:left;"><strong>Field-Oriented Motor Control</strong><br>Three-phase motor induced voltage and magnetic torque, rotating coordinate transforms, space-vector modulation headroom, and nested 20 kHz current plus 1 kHz stiffness loops.</td><td style="text-align:left;"><code>drive-01</code> to <code>drive-04</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>16</strong></td><td style="text-align:left;"><strong>Three-Phase Power Inverters</strong><br>Low-side resistor current sampling, scaled-integer motor packets, transistor switching losses and gate-drive charge pumps, ringing damping, and 4-layer circular board layout.</td><td style="text-align:left;"><code>drive-05</code> to <code>drive-12</code>, <code>drive-14</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>17</strong></td><td style="text-align:left;"><strong>Real-Time Motor Control Firmware</strong><br>Shift-add fixed-point trigonometry, timer-triggered analog sampling, 14-bit magnetic angle speed tracking, coil resistance/inductance calibration, cogging compensation, and zero-wait RAM execution.</td><td style="text-align:left;"><code>drive-13</code>, <code>drive-15</code> to <code>drive-21</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>18</strong></td><td style="text-align:left;"><strong>Planetary Geartrains and Actuator Bring-Up</strong><br>Reflected rotor inertia, 8:1 gear-tooth geometry, parametric 3D <strong>Computer-Aided Design</strong> (CAD), finite-element tooth stress analysis, tolerance stack-ups, oscilloscope switching checks, and haptic wheel graduation.</td><td style="text-align:left;"><code>drive-22</code> to <code>drive-30</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr></tbody></table><h3 id="part-v-battery-systems-and-solid-state-protection" tabindex="-1">Part V — Battery Systems and Solid-State Protection <a class="header-anchor" href="#part-v-battery-systems-and-solid-state-protection" aria-label="Permalink to &quot;Part V — Battery Systems and Solid-State Protection&quot;">​</a></h3><p>Part V engineers the touch-safe (under 22 V) <code>power</code> distribution spine that feeds twelve dynamic actuators without brownouts or hazardous fault currents. We model six-cell lithium-iron-phosphate battery dynamics, design microsecond solid-state circuit breakers, and test real short-circuit cutoffs on the bench (<a href="https://github.com/Ethanex8/apex/blob/main/systems/power/README.md" target="_blank" rel="noreferrer"><code>power</code> Reference</a>).</p><table tabindex="0"><thead><tr><th style="text-align:center;">Ch.</th><th style="text-align:left;">Title and Scope</th><th style="text-align:left;">Steps</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>19</strong></td><td style="text-align:left;"><strong>Battery Dynamics and State Estimation</strong><br>Six-cell lithium-iron-phosphate internal impedance and flat voltage plateaus, capacitive startup surge and regenerative braking energy, and nonlinear Kalman fuel-gauge estimation.</td><td style="text-align:left;"><code>power-01</code> to <code>power-03</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>20</strong></td><td style="text-align:left;"><strong>Solid-State Circuit Breakers</strong><br>Back-to-back transistor current blocking, transient-clamped inductive turn-off, 5 V step-down loop stability, emergency-stop latching, and thick-copper thermal board layout.</td><td style="text-align:left;"><code>power-04</code> to <code>power-11</code>, <code>power-14</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>21</strong></td><td style="text-align:left;"><strong>Power Supervision and Fault Testing</strong><br>Numerically stable C covariance updates, pre-trigger black-box fault logs, soft pre-charge short-circuit guards, thermistor temperature calibration, and sub-5 µs short-circuit bench tests.</td><td style="text-align:left;"><code>power-12</code> to <code>power-13</code>, <code>power-15</code> to <code>power-24</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr></tbody></table><h3 id="part-vi-rigid-body-kinematics-and-compliant-limbs" tabindex="-1">Part VI — Rigid-Body Kinematics and Compliant Limbs <a class="header-anchor" href="#part-vi-rigid-body-kinematics-and-compliant-limbs" aria-label="Permalink to &quot;Part VI — Rigid-Body Kinematics and Compliant Limbs&quot;">​</a></h3><p>Part VI combines three <code>drive</code> actuators into the 3-joint <code>limb</code> assembly that later bolts directly onto the quadruped as Front-Left Leg #1. We derive 3D rigid-body kinematics, recursive inverse dynamics, sensorless impact detection, and foot-space spring-damper hopping control (<a href="https://github.com/Ethanex8/apex/blob/main/systems/limb/README.md" target="_blank" rel="noreferrer"><code>limb</code> Reference</a>).</p><table tabindex="0"><thead><tr><th style="text-align:center;">Ch.</th><th style="text-align:left;">Title and Scope</th><th style="text-align:left;">Steps</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>22</strong></td><td style="text-align:left;"><strong>Rigid-Body Kinematics</strong><br>3D rotation matrices and rigid-body twists, exponential-map forward kinematics, closed-form geometric inverse kinematics with singularity clamping, and virtual-work Jacobian torque mapping.</td><td style="text-align:left;"><code>limb-01</code> to <code>limb-04</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>23</strong></td><td style="text-align:left;"><strong>Inverse Dynamics and Impedance Control</strong><br>Linear-time Newton-Euler gravity and inertia sweeps, 3D foot-space spring-damper control, and physics-engine verification with 64× reflected rotor inertia.</td><td style="text-align:left;"><code>limb-05</code> to <code>limb-07</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>24</strong></td><td style="text-align:left;"><strong>Contact Estimation and Hopping Control</strong><br>Sensorless momentum-based impact detection, smooth polynomial foot swing paths, spring-loaded pogo energy control, fixed-point C kinematics, and hardware-to-physics co-simulation.</td><td style="text-align:left;"><code>limb-08</code> to <code>limb-12</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>25</strong></td><td style="text-align:left;"><strong>Low-Inertia Limb Mechanics</strong><br>Hip-mounted belt transmissions, landing impulse and column buckling, neutral-axis cable routing, 4g landing stress analysis, vertical rail test stand CAD, and software torque limits.</td><td style="text-align:left;"><code>limb-13</code> to <code>limb-21</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>26</strong></td><td style="text-align:left;"><strong>Embedded Leg Control and Hopping</strong><br>1 kHz C leg control loop, joint zero-offset calibration, dynamic friction identification, weightless gravity float, soft drop landings, and 30-hop rail graduation.</td><td style="text-align:left;"><code>limb-22</code> to <code>limb-28</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr></tbody></table><h3 id="part-vii-optimal-balance-and-learned-locomotion" tabindex="-1">Part VII — Optimal Balance and Learned Locomotion <a class="header-anchor" href="#part-vii-optimal-balance-and-learned-locomotion" aria-label="Permalink to &quot;Part VII — Optimal Balance and Learned Locomotion&quot;">​</a></h3><p>Part VII assembles four legs, the <code>power</code> spine, and the <code>brain</code> computer into the complete 12-joint <code>walker</code> quadruped. We implement floating-base state estimation, receding-horizon convex force control, and scaled-integer (<strong>quantized</strong>) reinforcement-learning policies executing directly on our custom <code>mac</code> datapath (<a href="https://github.com/Ethanex8/apex/blob/main/systems/walker/README.md" target="_blank" rel="noreferrer"><code>walker</code> Reference</a>).</p><table tabindex="0"><thead><tr><th style="text-align:center;">Ch.</th><th style="text-align:left;">Title and Scope</th><th style="text-align:left;">Steps</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>27</strong></td><td style="text-align:left;"><strong>Floating-Base State Estimation</strong><br>Unanchored 18-degree-of-freedom body modeling, foot-contact Kalman speed/height estimation, friction-cone force optimization, capture-point footholds, motor voltage limits, and fall reflexes.</td><td style="text-align:left;"><code>walker-01</code> to <code>walker-07</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>28</strong></td><td style="text-align:left;"><strong>Centroidal Model Predictive Control</strong><br>Single-rigid-body linearization, 200 ms receding-horizon convex force optimization, predictive diagonal trotting, slip reflexes, and energy-efficiency benchmarks.</td><td style="text-align:left;"><code>walker-08</code> to <code>walker-14</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>29</strong></td><td style="text-align:left;"><strong>Learned Locomotion Policies</strong><br>Partially observable locomotion formulation, from-scratch policy-gradient reinforcement learning, parallel physics domain randomization, 16-bit <code>mac</code> export, and cycle-accurate walking simulation.</td><td style="text-align:left;"><code>walker-15</code> to <code>walker-22</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>30</strong></td><td style="text-align:left;"><strong>Quadruped Chassis and Field Walking</strong><br>Carbon sandwich torso CAD, diagonal-trot torsional stress analysis, twisted-pair motor-bus harnesses, overhead safety gantry, actuator system identification, and untethered walking graduation.</td><td style="text-align:left;"><code>walker-23</code> to <code>walker-34</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr></tbody></table><h3 id="part-viii-stereo-vision-and-autonomous-navigation" tabindex="-1">Part VIII — Stereo Vision and Autonomous Navigation <a class="header-anchor" href="#part-viii-stereo-vision-and-autonomous-navigation" aria-label="Permalink to &quot;Part VIII — Stereo Vision and Autonomous Navigation&quot;">​</a></h3><p>Part VIII mounts the <code>sight</code> synchronized stereo-camera head onto <code>walker</code>, phase-locking global-shutter exposures to <code>brain</code>&#39;s hardware timer within microseconds. We derive projective camera geometry, visual-inertial odometry, 3D obstacle mapping, and collision-free trajectory planning for untethered indoor autonomy (<a href="https://github.com/Ethanex8/apex/blob/main/systems/sight/README.md" target="_blank" rel="noreferrer"><code>sight</code> Reference</a>).</p><table tabindex="0"><thead><tr><th style="text-align:center;">Ch.</th><th style="text-align:left;">Title and Scope</th><th style="text-align:left;">Steps</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>31</strong></td><td style="text-align:left;"><strong>Stereo Camera Geometry</strong><br>Pinhole optics and lens distortion, stereo image rectification and quadratic depth error, feature optical flow with outlier rejection, inertial integration, and sub-50 µs shutter sync.</td><td style="text-align:left;"><code>sight-01</code> to <code>sight-06</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>32</strong></td><td style="text-align:left;"><strong>Visual-Inertial Odometry and Mapping</strong><br>Rotation-manifold visual-inertial state estimation, sparse bundle adjustment, loop closure, probabilistic 2.5D/3D obstacle grids, metric scale observability, and the 2 Mbps <code>brain</code>–<code>sight</code> link.</td><td style="text-align:left;"><code>sight-07</code> to <code>sight-13</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>33</strong></td><td style="text-align:left;"><strong>Motion Planning and Navigation Safety</strong><br>Robot-radius obstacle inflation with graph/tree path search, dynamic-window velocity tracking, 8-bit neural safety margins, 150 ms communication-timeout safe stops, and full autonomy simulation.</td><td style="text-align:left;"><code>sight-14</code> to <code>sight-18</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr><tr><td style="text-align:center;"><strong>34</strong></td><td style="text-align:left;"><strong>Stereo Vision Hardware and Autonomy</strong><br>Global-shutter stereo baseline sizing, rigid head pod CAD, shutter-sync cable interface, calibration target geometry, handheld room mapping, and untethered obstacle-avoiding quadruped graduation.</td><td style="text-align:left;"><code>sight-19</code> to <code>sight-28</code></td><td style="text-align:center;"><span class="book-status-upcoming">Upcoming</span></td></tr></tbody></table>',35)])])}const h=e(r,[["render",s]]);export{m as __pageData,h as default};
